// @wardenx/db — `bereavement_outreach` (M16 §3.3.4). One scheduled touchpoint per (contact × milestone),
// generated by the D4 death-anchored schedule: platform floor per risk tier, tenant may TIGHTEN (add
// contacts, move earlier within tier bounds, upgrade modality) but never drop a floor item or push it past
// its `due_at`. `late_grace_until` is the boundary the hourly miss worker judges against; a `lateAttempt`
// inside the grace re-opens the row to `in_progress` (audit-flagged, NOT a compliance failure).
//
// ── D4 CEILING: WHY `death_anchor_at`, NOT the spec's `death_date` ──────────────────────────────────────
// §3.3.4 denormalizes the plan's `death_date` (a DATE) and writes the ceiling CHECK as
//   EXTRACT(EPOCH FROM (due_at - death_date::timestamp)) / 86400 BETWEEN 0 AND 426
// The denormalization is right (ADR-0022 D1.2: PostgreSQL forbids a subquery in a CHECK, so the ceiling has
// to be a local-column comparison), but that expression cannot be created: `due_at` is TIMESTAMPTZ and
// `death_date::timestamp` is TIMESTAMP, and the implicit timestamp→timestamptz coercion PostgreSQL would
// insert is STABLE (it reads the session TimeZone), not IMMUTABLE — CHECK constraints reject it. So the
// denormalized anchor is stored as `death_anchor_at TIMESTAMPTZ NOT NULL` (the plan's death date resolved to
// the org's local start-of-day once, at row creation, by the schedule generator) and the ceiling subtracts
// two timestamptz values, which IS immutable. Identical semantics, legal DDL.
// 426 days = 396 (13 months) + 30 (grace), per §2.5.
//
// D12 / §3.6: NOT partitioned. Even 1,000 deaths × 5 contacts × 20 touchpoints is ~100K rows/year, and the
// dominant query ("what is due for my caseload this week") is a current-row btree read.
//
// TENANCY: organization_id + provider_entity_id NOT NULL, location_id nullable, denormalized from the plan.
// CROSS-MODULE FK POLICY: org/PE/location + the intra-M16 plan and contact parents are real FKs;
// assignee_user_id (M2 membership) and rendered_document_id (M22, D14 outbox back-ref) are logical uuid.
import { sql } from "drizzle-orm";
import { check, index, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";
import {
  bereavementAnniversaryMark,
  bereavementOutreachKind,
  bereavementOutreachStatus,
} from "../../enums";
import { locations } from "../locations";
import { organizations } from "../organizations";
import { providerEntities } from "../provider-entities";
import { bereavedContact } from "./bereaved-contacts";
import { bereavementPlan } from "./bereavement-plans";

export const bereavementOutreach = pgTable(
  "bereavement_outreach",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    organizationId: uuid("organization_id")
      .notNull()
      .references(() => organizations.id, { onDelete: "restrict" }),
    providerEntityId: uuid("provider_entity_id")
      .notNull()
      .references(() => providerEntities.id, { onDelete: "restrict" }),
    locationId: uuid("location_id").references(() => locations.id, { onDelete: "restrict" }),
    planId: uuid("plan_id")
      .notNull()
      .references(() => bereavementPlan.id, { onDelete: "restrict" }),
    bereavedContactId: uuid("bereaved_contact_id")
      .notNull()
      .references(() => bereavedContact.id, { onDelete: "restrict" }),

    kind: bereavementOutreachKind("kind").notNull(),
    status: bereavementOutreachStatus("status").notNull().default("scheduled"),
    anniversaryMark: bereavementAnniversaryMark("anniversary_mark"), // NULL for ad-hoc touchpoints

    // D4 — copied from the plan at row creation and IMMUTABLE thereafter; the ceiling CHECK reads it.
    deathAnchorAt: timestamp("death_anchor_at", { withTimezone: true }).notNull(),

    dueAt: timestamp("due_at", { withTimezone: true }).notNull(),
    lateGraceUntil: timestamp("late_grace_until", { withTimezone: true }).notNull(),
    startedAt: timestamp("started_at", { withTimezone: true }),
    completedAt: timestamp("completed_at", { withTimezone: true }),
    cancelledAt: timestamp("cancelled_at", { withTimezone: true }),
    cancellationReasonRedacted: text("cancellation_reason_redacted"), // D11 audit-denylisted

    assigneeUserId: uuid("assignee_user_id"), // overrides plan.assigned_counselor when set (M2 membership)

    // D14 — the M22 render handshake back-refs. M16 emits the request, M22 renders, M16's
    // `m22.document.rendered` consumer stamps these. M16 imports no M22 schema.
    renderedDocumentId: uuid("rendered_document_id"),
    m22RenderRequestedAt: timestamp("m22_render_requested_at", { withTimezone: true }),
    m22RenderedAt: timestamp("m22_rendered_at", { withTimezone: true }),

    // The schedule-generator policy version this row was produced under — audit replay (§7.15).
    policyVersionSnapshot: text("policy_version_snapshot"),

    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => ({
    planDueIdx: index("berv_outreach_plan_due_idx").on(t.planId, t.dueAt),
    contactDueIdx: index("berv_outreach_contact_due_idx").on(t.bereavedContactId, t.dueAt),
    // The hourly miss worker + the counselor "due in N days" dashboard both drive off this one.
    statusDueIdx: index("berv_outreach_status_due_idx").on(t.organizationId, t.status, t.dueAt),
    anniversaryIdx: index("berv_outreach_anniv_idx")
      .on(t.planId, t.anniversaryMark)
      .where(sql`anniversary_mark IS NOT NULL`),

    dueWithinPlanCeiling: check(
      "berv_outreach_due_within_ceiling",
      sql`EXTRACT(EPOCH FROM (due_at - death_anchor_at)) / 86400 BETWEEN 0 AND 426`,
    ),
    // The grace window can never precede the due date it is a grace ON.
    graceAfterDue: check("berv_outreach_grace_after_due", sql`late_grace_until >= due_at`),
    // §3.3.4's `kind != 'in_person_visit' OR true` is a tautology the spec itself annotates as a soft
    // placeholder ("binding rule lives in §5 contact_log"); the real D15 constraint is the CHECK pair on
    // bereavement_contact_log.source_encounter_id, so no no-op constraint is emitted here.
  }),
);

export type BereavementOutreachRow = typeof bereavementOutreach.$inferSelect;
export type NewBereavementOutreachRow = typeof bereavementOutreach.$inferInsert;
